.darma-loader-darma-b13-sewing-stitch { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .58); position: relative; overflow: hidden; }
.darma-loader-darma-b13-sewing-stitch::after { content: ''; position: absolute; bottom: 10%; left: 0; width: 100%; height: 34%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 32%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b13-sewing-stitch span { position: absolute; z-index: 2; bottom: 24%; left: 8%; height: 7%; width: 0; border-radius: 2px; background: repeating-linear-gradient(90deg, var(--accent) 0 calc(var(--loader-size, 112px) * .05), transparent calc(var(--loader-size, 112px) * .05) calc(var(--loader-size, 112px) * .085)); animation: darma-loader-darma-b13-sewing-stitch-stitch calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b13-sewing-stitch .darma-loader-darma-b13-sewing-stitch__needle { position: absolute; z-index: 3; top: 2%; left: 9%; width: 4%; height: 44%; border-radius: 2px 2px 60% 60%; background: linear-gradient(#94a3b8, #f1f5f9); animation: darma-loader-darma-b13-sewing-stitch-punch calc(var(--loader-speed, 1s) * 3) linear infinite; }
@keyframes darma-loader-darma-b13-sewing-stitch-stitch { 0% { width: 0; } 18% { width: 16%; } 36% { width: 32%; } 54% { width: 48%; } 72% { width: 64%; } 92% { width: 78%; } 100% { width: 0; } }
@keyframes darma-loader-darma-b13-sewing-stitch-punch { 0% { transform: translate(0, 0); } 9% { transform: translate(0, 52%); } 18% { transform: translate(0, 0); } 27% { transform: translate(calc(var(--loader-size, 112px) * .16), 0); } 36% { transform: translate(calc(var(--loader-size, 112px) * .16), 52%); } 45% { transform: translate(calc(var(--loader-size, 112px) * .32), 0); } 54% { transform: translate(calc(var(--loader-size, 112px) * .32), 52%); } 63% { transform: translate(calc(var(--loader-size, 112px) * .48), 0); } 72% { transform: translate(calc(var(--loader-size, 112px) * .48), 52%); } 84% { transform: translate(calc(var(--loader-size, 112px) * .64), 0); } 92% { transform: translate(calc(var(--loader-size, 112px) * .64), 52%); } 100% { transform: translate(0, 0); } }

